 },
 "risks": [
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "With only 11 cases, it is highly improbable to achieve useful statistical power to test the hypothesis and differentiate between the various criteria for identifying the 'largest gainer'."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player absence can coincide with other team changes (e.g., coaching adjustments, other player injuries, schedule difficulty, opponent quality, team performance trends) that could confound the observed redistribution of offensive roles. Without robust controls, attributing changes solely to the absent player's profile and the 'closest' teammate is problematic."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "The hypothesis proposes multiple criteria for identifying the 'closest teammate' ('closest pre-absence initiation profile *or* most minutes / initiations / same-position minutes'). Testing these alternatives without a pre-specified hierarchy or correction for multiple comparisons will inflate Type I error rates."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The definitions of 'initiation profile' and 'primary types' need to be precisely operationalized from the 'derived play-type possession records'. The reliability and consistency of these derived metrics across different players and teams could impact the validity of the analysis."
  },
  {
   "code": "BASE_RATE",
   "text": "The baseline rate of teammates gaining initiations or specific play types even without a key player's absence needs to be considered. The 'largest gainer' might not represent a statistically significant or practically meaningful change if the overall distribution of roles is highly dynamic."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.05,
  "untestable": 0.6,
  "artifact": 0.1,
  "uncertain": 0.2
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The causal effect of a primary player's absence on the distribution of offensive 'primary types' among remaining teammates, specifically identifying if the teammate with the closest pre-absence profile (defined by initiation profile, minutes, initiations, or same-position minutes) experiences the largest gain in those 'primary types'.",
  "unit": "An 'absence spell' of a primary offensive player (defined as missing a minimum number of consecutive games, e.g., 3+ games).",
  "sample": "The available 11 cases of absence spells (n=148 total spells). This sample size is critically insufficient for a robust analysis.",
  "power": "Statistical power is expected to be very low due to the small sample size of 11 cases. A power analysis at this sample size would likely indicate that only very large effects could be detected, if at all. To achieve adequate power (e.g., 80% for a medium effect size), a significantly larger sample of absence spells (likely 50-100+) would be required, necessitating data from many more seasons or a broader definition of 'case'.",
  "controls": "Potential confounding variables to control for include: opponent strength (e.g., via ELO ratings), game context (e.g., pace, score differential), presence/absence of other key players, coaching changes, recent team performance trends, and the specific role/position of the absent player. A difference-in-differences approach comparing teammate play types before and after absence, relative to a control period, would be considered.",
  "falsification": "The hypothesis would be falsified if the teammate identified by the proposed criteria (closest profile, most minutes, etc.) is not consistently the largest gainer in the absent player's primary types, or if the observed gains are not statistically significant compared to a baseline or control group.",
  "multiplicity": "Given multiple criteria for 'closest teammate', a primary criterion must be pre-specified (e.g., 'closest initiation profile' as the main test). Other criteria would be explored as secondary analyses with appropriate multiplicity corrections (e.g., Bonferroni, FDR). Alternatively, a composite score combining these factors could be developed prior to analysis.",
  "decision_rule": "The primary outcome measure would be the statistically significant increase in the identified teammate's usage of the absent player's 'primary types' during the absence spell compared to their pre-absence usage, and compared to other teammates. A p-value threshold of 0.05 would be applied, with adjustments for multiplicity if multiple criteria are tested simultaneously. Due to low power, emphasis would also be placed on effect size.",
  "data_version": "NBA 2022-23 to 2025-26 seasons (regular season and playoffs where available). Per-game files from NBA stats API and derived play-type possession records."
 }
}

